n = 12
fixed = {3: 8, 8: 2}

# Let's use a different approach - use a list to track vectors and count references
def solve_costas(n, fixed):
    used_rows = set(fixed.values())
    solution = [None] * n
    for c, r in fixed.items():
        solution[c] = r

    # vector -> count of how many pairs produce it
    vec_count = {}
    fixed_items = sorted(fixed.items())
    for i, (c1, r1) in enumerate(fixed_items):
        for c2, r2 in fixed_items[i+1:]:
            dr = r2 - r1
            dc = c2 - c1
            vec_count[(dr, dc)] = vec_count.get((dr, dc), 0) + 1

    cols_to_fill = [c for c in range(n) if c not in fixed]

    def backtrack(idx):
        if idx == len(cols_to_fill):
            return solution[:]

        c = cols_to_fill[idx]
        available = [r for r in range(n) if r not in used_rows]

        for r in available:
            # Check conflicts with all placed marks
            conflict = False
            new_vecs = []  # vectors that would be newly created
            for c2 in range(n):
                r2 = solution[c2]
                if r2 is not None and c2 != c:
                    dr = r - r2
                    dc = c - c2
                    if dc > 0:
                        vec = (dr, dc)
                    else:
                        vec = (-dr, -dc)
                    if vec in vec_count and vec_count[vec] > 0:
                        conflict = True
                        break
                    new_vecs.append(vec)

            if conflict:
                continue

            # Place the mark
            for v in new_vecs:
                vec_count[v] = vec_count.get(v, 0) + 1
            used_rows.add(r)
            solution[c] = r

            result = backtrack(idx + 1)
            if result:
                return result

            # Undo
            solution[c] = None
            used_rows.remove(r)
            for v in new_vecs:
                vec_count[v] -= 1
                if vec_count[v] == 0:
                    del vec_count[v]

        return None

    return backtrack(0)

result = solve_costas(n, fixed)
